import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { registerRootComponent } from "expo";

const login = (email, password) =>
  new Promise((res) => setTimeout(() => res({ token: "tok_" + email }), 200));

function App() {
  const [status, setStatus] = useState("Нэвтрээгүй");

  const signIn = async () => {
    const res = await login("bat@shop.mn", "нууц");
    await AsyncStorage.setItem("token", res.token);
    setStatus("Нэвтэрлээ");
  };

  return (
    <View style={styles.s}>
      <Text nativeID="status" style={styles.t}>{status}</Text>
      <Pressable nativeID="login" style={styles.btn} onPress={signIn}>
        <Text style={styles.bt}>Нэвтрэх</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 16, justifyContent: "center", alignItems: "center" },
  t: { fontSize: 20, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", paddingVertical: 14, paddingHorizontal: 28, borderRadius: 12 },
  bt: { color: "#fff", fontSize: 16, fontWeight: "bold" },
});

registerRootComponent(App);
